    function run(uint dummy) public payable {
        require(true);

        // The contract starts unfunded: no balance available to it.
        uint balBefore = address(c).balance;

        // First destructive call by the owner (this contract deployed c).
        c.sudicideAnyone();

        // Read-only observation after destruction.
        uint balAfter1 = address(c).balance;

